export type KaminoInitObligationInput<
  TAccountFeePayer extends InstructionSignerInput = InstructionSignerInput,
  TAccountBank extends InstructionAccountInput = InstructionAccountInput,
  TAccountSignerTokenAccount extends InstructionAccountInput = InstructionAccountInput,
  TAccountLiquidityVaultAuthority extends InstructionAccountInput = InstructionAccountInput,
  TAccountLiquidityVault extends InstructionAccountInput = InstructionAccountInput,
  TAccountIntegrationAcc2 extends InstructionAccountInput = InstructionAccountInput,
  TAccountUserMetadata extends InstructionAccountInput = InstructionAccountInput,
  TAccountLendingMarket extends InstructionAccountInput = InstructionAccountInput,
  TAccountLendingMarketAuthority extends InstructionAccountInput = InstructionAccountInput,
  TAccountIntegrationAcc1 extends InstructionAccountInput = InstructionAccountInput,
  TAccountMint extends InstructionAccountInput = InstructionAccountInput,
  TAccountReserveLiquiditySupply extends InstructionAccountInput = InstructionAccountInput,
  TAccountReserveCollateralMint extends InstructionAccountInput = InstructionAccountInput,
  TAccountReserveDestinationDepositCollateral extends InstructionAccountInput =
    InstructionAccountInput,
  TAccountObligationFarmUserState extends InstructionAccountInput = InstructionAccountInput,
  TAccountReserveFarmState extends InstructionAccountInput = InstructionAccountInput,
  TAccountKaminoProgram extends InstructionAccountInput = InstructionAccountInput,
  TAccountFarmsProgram extends InstructionAccountInput = InstructionAccountInput,
  TAccountCollateralTokenProgram extends InstructionAccountInput = InstructionAccountInput,
  TAccountLiquidityTokenProgram extends InstructionAccountInput = InstructionAccountInput,
  TAccountInstructionSysvarAccount extends InstructionAccountInput = InstructionAccountInput,
  TAccountRent extends InstructionAccountInput = InstructionAccountInput,
  TAccountSystemProgram extends InstructionAccountInput = InstructionAccountInput,
> = {
  /**
   * Pays to init the obligation and pays a nominal amount to ensure the obligation has a
   * non-zero balance.
   */
  feePayer: TAccountFeePayer;
  bank: TAccountBank;
  /**
   * The fee payer must provide a nominal amount of bank tokens so the obligation is not empty.
   * This amount is irrecoverable and and will prevent the obligation from ever being closed,
   * even if the bank is otherwise empty (Kamino normally closes empty obligations automatically)
   */
  signerTokenAccount: TAccountSignerTokenAccount;
  /**
   * The liquidity vault authority (PDA that will own the Kamino obligation). Note: Kamino needs
   * this to be mut because `deposit` might return the rent here
   */
  liquidityVaultAuthority: TAccountLiquidityVaultAuthority;
  /** Used as an intermediary to deposit a nominal amount of token into the obligation. */
  liquidityVault: TAccountLiquidityVault;
  /**
   * The obligation account to be created. Note that the key was already derived when
   * initializing the bank, and this must match the obligation recorded at that time.
   */
  integrationAcc2: TAccountIntegrationAcc2;
  userMetadata: TAccountUserMetadata;
  lendingMarket: TAccountLendingMarket;
  lendingMarketAuthority: TAccountLendingMarketAuthority;
  integrationAcc1: TAccountIntegrationAcc1;
  /** Bank's liquidity token mint (e.g., USDC). Kamino calls this the `reserve_liquidity_mint` */
  mint: TAccountMint;
  reserveLiquiditySupply: TAccountReserveLiquiditySupply;
  /** The reserve's mint for tokenized representations of Kamino deposits. */
  reserveCollateralMint: TAccountReserveCollateralMint;
  /**
   * The reserve's destination for tokenized representations of deposits. Note: the
   * `reserve_collateral_mint` will mint tokens directly to this account.
   */
  reserveDestinationDepositCollateral: TAccountReserveDestinationDepositCollateral;
  /** Required if the Kamino reserve has an active farm. */
  obligationFarmUserState?: TAccountObligationFarmUserState;
  /** Required if the Kamino reserve has an active farm. */
  reserveFarmState?: TAccountReserveFarmState;
  kaminoProgram?: TAccountKaminoProgram;
  /** Farms program for Kamino staking functionality */
  farmsProgram?: TAccountFarmsProgram;
  /** Note: the collateral token always uses Token classic, never Token22. */
  collateralTokenProgram?: TAccountCollateralTokenProgram;
  /**
   * Note: Kamino does not have full Token22 support, certain Token22 features are disallowed.
   * Expect this to update over time. Check with the Kamino source.
   */
  liquidityTokenProgram: TAccountLiquidityTokenProgram;
  instructionSysvarAccount?: TAccountInstructionSysvarAccount;
  rent?: TAccountRent;
  systemProgram?: TAccountSystemProgram;
  amount: KaminoInitObligationInstructionDataArgs["amount"];
};

